import { Lesson, Question, Topic } from '../types/database';

type Case = { prompt: string; answer: string; wrong: [string,string,string]; why: string };
type Unit = { id: string; domain: string; title: string; intro: string; terms: [string,string][]; sections: [string,string][]; examples: [string,string,string][]; cases: Case[]; sources?: {title:string;url:string}[] };
const units: Unit[] = [
{
 id:'measurement_traceability',domain:'d1',title:'Mass Measurement, Reagent Handling & Traceable Time',
 intro:'Connect balance technique, reagent identity, final volume, and clear records to a defensible preparation.',
 terms:[['Tare','Subtract the container mass so the displayed value represents the material added.'],['Traceability','A documented connection from a result back to samples, reagents, equipment, and actions.'],['ISO date','A date written as YYYY-MM-DD to reduce ambiguity.']],
 sections:[
 ['Planning a defensible preparation','Read the approved procedure and calculate the required amount before collecting materials. Check the exact chemical form: an anhydrous salt and its hydrate have different formula masses. Verify identity, grade, storage, expiration, and lot. Select a balance whose operating range and readability suit the required tolerance; readability alone does not establish accuracy. Check calibration status and perform required daily checks. A convenient bottle is not automatically the correct reagent.'],
 ['Weighing without introducing error','Place a clean compatible container on a stable, level balance and tare it. Close draft shields where fitted and wait for a stable reading. Avoid weighing hot containers: temperature differences and air movement can disturb results. Add material with a clean tool and keep original stock uncontaminated. Never return excess to the stock bottle. Record the actual mass with the instrument-supported digits, not a rounded target that hides the observed value.'],
 ['From measured mass to usable solution','Dissolve in less than the required final volume, then bring to volume with suitable calibrated glassware according to the procedure. Label identity, concentration, preparation date, preparer, storage, and hazards as required. Record actual mass, final volume, reagent lot, and balance identifier so another person can reconstruct the preparation. If the wrong reagent form was used, stop and report; a later label cannot repair the underlying calculation.'],
 ['Dates, time, and handoffs','Use unambiguous dates and 24-hour time. Record the time zone when records cross locations. Midnight is 00:00 at the beginning of the new date; noon is 12:00. Record events when they occur, including deviations. A handoff should state what was prepared, its status, storage location, and any unresolved issue. Do not invent a missing timestamp from memory or imply a material is released while review is pending.']
 ],examples:[['Hydrated reagent','Prepare 100 mL of 0.100 M salt with formula mass 250 g/mol.','Convert 100 mL to 0.100 L. Required moles = 0.100 mol/L × 0.100 L = 0.0100 mol. Mass = 0.0100 mol × 250 g/mol = 2.50 g. Use the formula mass for the actual bottle form.'],['Unambiguous handoff','A preparation finishes at 9:05 PM on September 30, 2026.','Record 2026-09-30 21:05 with the applicable time zone, actual observations, and preparer identity.']],
 cases:[{prompt:'A balance reads 2.497 g when the target is 2.500 g. What should be entered as the observed mass?',answer:'2.497 g, followed by assessment against the procedure tolerance',wrong:['2.500 g because that was the target','2.5 g to hide the small difference','No mass because the balance is calibrated'],why:'Record what was measured. Acceptance is a separate comparison with the approved tolerance.'},{prompt:'A reagent bottle contains a hydrate but the calculation used the anhydrous formula mass. What is the best response?',answer:'Stop and recalculate using the actual reagent form before proceeding',wrong:['Use the same mass because the names are similar','Correct the label after preparation','Ignore water in the formula'],why:'The required mass depends on the formula mass of the chemical form actually weighed.'}]
},
{
 id:'culture_counting',domain:'d1',title:'Culture Assessment, Cell Counts & Viability Calculations',
 intro:'Distinguish cell number, viability, culture purity, and growth measurements rather than treating them as interchangeable.',
 terms:[['Viability','The proportion classified as living by the defined assay.'],['CFU','A colony-forming unit; a colony may arise from one cell or a cluster.'],['Hemocytometer','A counting chamber with a defined area and depth.']],
 sections:[
 ['Choose a measurement that answers the question','Optical density measures turbidity, a direct chamber count estimates particles or cells, a viability stain classifies membrane integrity under specified conditions, and plating estimates colony-forming units. None measures every aspect of culture quality. Dead cells may still contribute to turbidity or direct counts. Clumps may yield one colony. A change in OD alone does not establish purity, viability, or the identity of an organism.'],
 ['Obtain a representative chamber count','Mix the suspension gently but thoroughly immediately before sampling. Load the chamber according to its instructions without bubbles or overfilling. Use the stated counting area and a consistent boundary rule, such as counting top/left edges and excluding bottom/right edges. Count multiple defined squares. A large difference among squares suggests poor mixing, uneven loading, or clumping; address the cause instead of selecting the most convenient field.'],
 ['Calculate concentration and viable yield','For a standard large hemocytometer square with area 1 mm² and depth 0.1 mm, volume is 0.1 mm³ = 0.0001 mL. Mean cells per large square × 10,000 × reciprocal dilution factor gives cells/mL. Verify chamber geometry before using that factor. Viability = viable cells / all counted cells × 100%. Viable concentration uses viable counts, and total viable yield also requires suspension volume.'],
 ['Recognize an unacceptable culture','Inspect appearance, expected morphology, growth, and contamination checks using the approved criteria. Unexpected cloudiness, pH indicator changes, or mixed morphology require investigation; they are not enough to identify the contaminant. Segregate suspect material and notify the instructor or supervisor. Culture work requires approved organisms, containment, training, and a local SOP. Do not rescue contaminated cultures by adding unapproved antibiotics or mixing them into clean cultures.']
 ],examples:[['Concentration and viability','Four large squares contain 42, 38, 40, and 40 viable cells after a 1:1 stain mixture. There are 20 nonviable cells total.','Mean viable count = 160/4 = 40. The stain mixture is a twofold dilution. Viable concentration = 40 × 10,000 × 2 = 800,000 cells/mL. Viability = 160/(160+20) × 100 = 88.9%.'],['Plate count','A plate has 62 colonies from 0.100 mL of a 10^-4 dilution.','Original concentration = 62 / (0.100 mL × 10^-4) = 6.2 × 10^6 CFU/mL. Apply the validated plate-count acceptance range and replicate rules.']],
 cases:[{prompt:'A 1:1 mixture of cells and stain is counted. Which dilution correction is required?',answer:'Multiply the measured concentration by 2',wrong:['Multiply by 1','Divide by 2','Multiply by 10'],why:'One part cells plus one part stain doubles the total volume and halves cell concentration.'},{prompt:'OD increases but viable cell counts decrease. What is justified?',answer:'Investigate because turbidity and viability measure different properties',wrong:['All cells must be alive','The culture is proven pure','Ignore the viability assay'],why:'Turbidity can include dead cells and other particles; it does not establish viability.'}]
},
{
 id:'qpcr_diagnostics',domain:'d2',title:'Real-Time PCR, RT-qPCR & Molecular Diagnostic Controls',
 intro:'Read amplification curves and recognize what controls permit—or prevent—you from concluding.',
 terms:[['Cq','The cycle at which fluorescence crosses a defined analysis threshold.'],['Reverse transcription','Conversion of RNA to complementary DNA.'],['Inhibition','Suppression of amplification by substances or conditions in a sample.']],
 sections:[
 ['Endpoint versus real-time measurement','Conventional PCR amplifies a target and commonly examines product after cycling. qPCR monitors fluorescence during amplification. A dye can bind double-stranded DNA, while a sequence-specific probe provides target-dependent fluorescence. Dye signal can include nonspecific products, so specificity must be checked. Reverse-transcription qPCR begins with RNA converted into cDNA; real-time monitoring and reverse transcription describe different steps and should not be confused.'],
 ['Interpret Cq only in a validated comparison','With the same validated assay, threshold method, and adequate amplification efficiency, more starting target generally crosses the threshold earlier. Cq is not an absolute concentration or a universal positivity rule. Threshold settings, inhibition, efficiency, and sample processing can affect it. Absolute quantification uses calibrated standards and a validated range. Relative expression requires appropriate reference genes and comparable assay performance, rather than comparing unrelated Cq values directly.'],
 ['Controls follow the full workflow','A no-template control checks contamination introduced in amplification setup. An extraction blank follows extraction and can reveal contamination there. A positive control demonstrates the detection system can work. An internal control can reveal sample inhibition or processing failure. For RNA assays, a no-reverse-transcriptase control can reveal DNA-derived signal. A negative target result is not defensible if required internal controls failed.'],
 ['Troubleshoot before reporting','If the no-template control amplifies, review contamination and nonspecific amplification according to acceptance rules; do not declare every sample positive. If only a sample internal control fails, investigate inhibition or extraction failure. Examine curve shape, replicate agreement, and any required melt-curve evidence. Keep pre-amplification reagents separated from amplified products and use the approved workflow. Change analysis settings only with justification and retain the original record.']
 ],examples:[['Starting target','Two valid samples have Cq 20 and 23 with ideal doubling and the same assay.','A difference of three cycles corresponds approximately to 2³ = 8-fold starting target. The Cq-20 sample has more target. This estimate requires the stated efficiency assumption; it is not a clinical decision cutoff.'],['Failed internal control','Target is not detected and the required internal control is also not detected.','Treat the result as invalid or indeterminate under the procedure and investigate. The missing internal control prevents a reliable negative conclusion.']],
 cases:[{prompt:'Target and required internal control both fail to amplify. What should the technician do?',answer:'Investigate the invalid result rather than report a negative',wrong:['Report a confirmed negative','Report a confirmed positive','Delete the internal control'],why:'Control failure may indicate inhibition or processing failure; target absence alone is insufficient.'},{prompt:'In the same valid ideal-efficiency assay, Cq values differ by 3 cycles. What approximate starting-target ratio follows?',answer:'8-fold',wrong:['3-fold','6-fold','No relationship under any conditions'],why:'With doubling each cycle, the ratio is 2³ = 8; actual efficiency must support the approximation.'}],
 sources:[{title:'Bio-Rad: qPCR data interpretation',url:'https://www.bio-rad.com/en-us/life-science-research/support/webinars/qpcr-unvalidated-what-your-data-isnt-telling-you-session-1?ID=1743019935934'}]
},
{
 id:'immunoassay_validation',domain:'d2',title:'ELISA, Immunoassays & Assay Validation',
 intro:'Connect antibody recognition, assay format, controls, and analytical performance to trustworthy results.',
 terms:[['Antigen','A molecular feature recognized by an antibody.'],['Specificity','The ability of an assay to distinguish the intended target from other substances.'],['Recovery','Measured amount relative to an expected amount added to a sample.']],
 sections:[
 ['Understand what creates the signal','In a sandwich ELISA, a capture antibody binds target and a detection antibody recognizes another accessible site. An enzyme-linked detection system converts substrate into a measurable signal. Direct and indirect formats differ in how the detectable label is attached. A competitive assay may show lower signal as target concentration increases. Always determine the format before assuming that higher absorbance means more analyte.'],
 ['Map the plate before pipetting','Identify standards, blanks, required quality controls, samples, and replicates on a plate map. Label sample dilutions and check reagent identity and storage. Maintain the prescribed incubation sequence, timing, and wash conditions. Inadequate washing can leave unbound detection reagent and raise background. Avoid letting wells dry when the procedure prohibits it. Edge effects and inconsistent timing can create a pattern unrelated to sample concentration.'],
 ['Validation is broader than a good-looking curve','Evaluate characteristics relevant to the intended use: precision, accuracy or recovery, specificity, range, and detection or quantification capability. Calibration establishes a response relationship; validation supplies evidence the method is fit for purpose. A high R² does not prove specificity or acceptable control recovery. Samples can have matrix effects; dilution agreement and spike recovery may help evaluate them under a validated plan.'],
 ['Accept, investigate, or repeat','Compare all required controls and standards with predefined acceptance criteria before reporting samples. Repeat testing must follow the investigation procedure, not continue until a desirable answer appears. If an unknown lies outside the validated range, use an approved dilution or reanalysis approach. Record the original result, investigation, and any repeat. An assay result is only as defensible as its identity, controls, calibration, and traceability.']
 ],examples:[['Back-calculate a dilution','A diluted sample is 18 ng/mL from a valid curve; the sample was diluted 1:5.','Original concentration = 18 × 5 = 90 ng/mL. Confirm that the dilution and matrix are permitted and that controls pass.'],['Recovery','A blank matrix spiked with 50 ng/mL yields 45 ng/mL.','Recovery = 45/50 × 100 = 90%. Compare this with the protocol acceptance range; 90% is not automatically acceptable for every method.']],
 cases:[{prompt:'All samples show high background after an ELISA run. Which procedural issue should be investigated?',answer:'Incomplete removal of unbound detection reagent during washing',wrong:['Guaranteed high target in every sample','The plate map is unnecessary','A high R² proves no problem exists'],why:'Unbound detection reagent can generate nonspecific background; controls and procedural records help identify the cause.'},{prompt:'A curve has high R² but required quality controls fail. What is the best decision?',answer:'Investigate and apply the predefined run acceptance rules',wrong:['Release every result because R² is high','Delete the controls','Choose only passing samples'],why:'Curve fit alone does not establish overall assay validity.'}]
},
{
 id:'chromatography',domain:'d2',title:'Chromatography, Protein Purification & FTIR Identification',
 intro:'Choose separation methods by molecular properties and distinguish purification from chemical identification.',
 terms:[['Stationary phase','The material retained in the column that interacts with sample components.'],['Mobile phase','The fluid carrying the sample through a separation.'],['Elution','Movement of retained molecules out of the column.']],
 sections:[
 ['Separation depends on different interactions','Chromatography separates mixture components because they interact differently with stationary and mobile phases. Affinity chromatography uses selective binding, ion exchange depends on charge under the chosen pH conditions, and size exclusion separates by access to pores. In size exclusion, larger molecules excluded from pores often leave earlier than smaller molecules. No single separation method is best for every target. Choose based on the target and contaminants.'],
 ['Follow the purification sequence','An affinity workflow commonly includes equilibration, sample loading, washing to remove unbound material, and elution of retained target. Collect and label fractions rather than assuming all target is in one tube. Monitor pressure, flow, and any detector signal within equipment limits. Check fractions for identity, purity, and activity using appropriate assays. A visible chromatographic peak does not by itself identify the protein or prove it is active.'],
 ['Balance yield with purity','A purification can lose target while removing contaminants. Yield compares recovered target with starting target; purity describes the target proportion in the product. Total protein is not automatically target protein. Increasing apparent total protein recovery can simply retain more contaminants. Use the measurement appropriate to the claim and retain fraction identities. Protein expression and purification must preserve conditions needed for the intended activity or stability.'],
 ['FTIR asks a different question','Fourier-transform infrared spectroscopy measures infrared absorption associated with molecular vibrations and produces a spectrum commonly plotted against wavenumber. It can support functional-group or material identification when compared with suitable references. It is not the same measurement as UV-visible absorbance for concentration. Prepare and compare samples with the appropriate background and sampling method; water, contaminants, and preparation can affect spectral interpretation.']
 ],examples:[['Purification yield','A process starts with 20 mg of target protein and recovers 12 mg.','Target yield = 12/20 × 100 = 60%. This says nothing by itself about the contaminant content of the recovered material.'],['Fraction selection','A UV detector gives a strong peak, but a target-specific assay is negative in those fractions.','Do not identify the peak as the target. Other absorbing material may generate the signal; use verified identity and purity measurements.']],
 cases:[{prompt:'Which mechanism is used in ion-exchange chromatography?',answer:'Differential interaction based on charge under the selected conditions',wrong:['Only molecular size','Antibody recognition in every column','All molecules move at the same speed'],why:'Ion exchange uses charged stationary phases; pH and ionic strength affect binding and elution.'},{prompt:'A process recovers 12 mg of target from 20 mg initially. What is the yield?',answer:'60%',wrong:['40%','167%','12%'],why:'Yield = recovered target / starting target × 100 = 12/20 × 100.'}]
},
{
 id:'flow_automation',domain:'d2',title:'Flow Cytometry, Cell Sorting & Laboratory Automation',
 intro:'Interpret individual-cell measurements and recognize how automation can reproduce both correct work and systematic errors.',
 terms:[['Event','One measured particle passage through the detection region.'],['Gate','A defined selection of events for analysis.'],['Compensation','Correction for fluorescence spillover in conventional multicolor flow cytometry.']],
 sections:[
 ['What a flow cytometer measures','Cells in suspension pass through a detection region where lasers generate scatter and fluorescence signals. Forward scatter can relate to size and side scatter to internal complexity, but neither alone determines identity. Fluorescent labels allow marker-based analysis. Debris, dead cells, and cell aggregates can distort apparent populations. A dot plot represents measurements on events, not automatically a pure population of living single cells.'],
 ['Build a defensible analysis','Use appropriate instrument checks and controls, then identify relevant events through a documented gating strategy. Exclude debris, distinguish singlets from aggregates, and assess viability when required. Unstained controls help evaluate background; single-color controls support compensation. Fluorescence-minus-one controls can help place a boundary in a multicolor panel. Controls have different purposes and are not interchangeable. Retain the strategy so analysis can be reviewed.'],
 ['Analysis is different from sorting','An analyzer measures populations. A sorter additionally separates selected events into collection vessels. Collection purity, viability, and recovery can differ from the original gated percentage. Sample preparation and biosafety requirements matter, especially with aerosol-generating equipment. Only trained personnel should operate approved settings and containment. A gate is an analysis decision, not proof that every collected cell behaves identically.'],
 ['Automated systems still need verification','Robotic pipetting, plate readers, and software can improve throughput and consistency, but a wrong plate map or unit can be repeated across hundreds of wells. Verify identifiers, labware positions, volumes, tip compatibility, method version, and control locations. Validate performance, monitor errors, and reconcile output with original records. Never reach into moving machinery or bypass an interlock; pause and use the authorized recovery procedure.']
 ],examples:[['Report a population','Of 8,000 viable singlet events, 2,000 fall in a marker-positive gate.','The marker-positive fraction of that defined population is 2,000/8,000 × 100 = 25%. State the denominator and gating method.'],['Automation error','The robot completes a run, but the source plate was rotated.','Completion does not establish sample identity. Hold affected results, preserve the map and logs, and investigate the mapping error.']],
 cases:[{prompt:'Which control supports conventional multicolor fluorescence compensation?',answer:'Appropriate single-color controls',wrong:['A handwritten plate title alone','Only a target-negative patient sample','A larger sample size without controls'],why:'Single-color controls reveal spillover into other channels; they do not replace other assay controls.'},{prompt:'A robot finishes with no error message, but samples were mapped incorrectly. What follows?',answer:'Hold results and investigate identity before reporting',wrong:['Release because the robot completed','Rename samples from memory','Remove all run logs'],why:'Automation can successfully execute the wrong mapping; traceability must be verified.'}],
 sources:[{title:'Thermo Fisher: flow cytometry controls',url:'https://www.thermofisher.com/ch/en/home/life-science/cell-analysis/flow-cytometry/flow-cytometry-learning-center/controls-compensation-calibration-information.html'}]
},
{
 id:'workplace_safety',domain:'d3',title:'Safety Communication, Chemical Storage & Energy Isolation',
 intro:'Practice reporting, storage decisions, ethical conduct, and recognition of hazards that require authorized personnel.',
 terms:[['Near miss','An event that could have caused harm but did not.'],['Incompatibility','A combination that can react dangerously or compromise safe storage.'],['Lockout/tagout','A controlled process for isolating hazardous energy during servicing.']],
 sections:[
 ['Build a reporting culture','Report hazards and near misses promptly even when no one was injured. Describe the location, materials or equipment, observed conditions, immediate protective actions, and people potentially affected. Avoid blame or unsupported conclusions. Stop work when required and communicate clearly at handoff. Ethical conduct includes honest records, respect, confidentiality, and raising concerns when production pressure conflicts with safety or valid results.'],
 ['Storage follows hazards, not the alphabet','Consult the SDS and local chemical hygiene plan for compatibility, containment, ventilation, and temperature requirements. Separate incompatible classes; alphabetical ordering alone can place reactive chemicals together. Keep labels legible and containers suitable, and use secondary containment where required. Never infer compatibility from similar bottle size or color. An unknown container requires isolation and authorized identification or disposal, rather than smelling or testing it casually.'],
 ['Recognize hazardous energy','Moving machinery may have electrical, pneumatic, hydraulic, thermal, or stored mechanical energy. Turning a control switch off is not necessarily energy isolation. Lockout/tagout is performed under the employer procedure by authorized, trained personnel, including required isolation and verification steps. A student technician should recognize the boundary of their authorization, stop, report, and keep clear. Do not remove another person’s lock or bypass an interlock.'],
 ['Emergency action is role-specific','Know exits, eyewash and shower locations, alarm procedures, and contacts before work begins. On discovering fire, a major spill, or an uncontrolled hazard, alert others and follow the emergency plan. Only trained and authorized personnel perform the permitted response. PPE and spill kits do not make every incident safe to handle. Reentry and restart require authorization; completing a task is secondary to protecting people.']
 ],examples:[['Near miss report','A frayed power cable sparks, but no one is injured.','Stop use, keep others clear, notify the supervisor, and document the event as a near miss under the reporting procedure. Do not continue because no injury occurred.'],['Unknown chemical','A container has an illegible label.','Do not use it or infer identity from smell. Secure the area as required and request authorized identification or disposal.']],
 cases:[{prompt:'An equipment guard is missing but the machine still runs. What is appropriate?',answer:'Stop use and report for authorized evaluation',wrong:['Operate more carefully','Bypass the guard sensor','Ask an untrained student to repair it'],why:'A functioning machine can still be unsafe; guarding and authorized servicing remain required.'},{prompt:'Why is alphabetical chemical storage insufficient?',answer:'It can place incompatible chemicals next to each other',wrong:['All chemicals are compatible','Bottle size determines hazard','Only expiration dates matter'],why:'Storage must consider hazard compatibility and the local chemical hygiene plan.'}]
},
{
 id:'math_statistics',domain:'d4',title:'Significant Figures, Logarithmic pH & Descriptive Statistics',
 intro:'Calculate carefully, state units, and distinguish mathematical results from assay acceptance decisions.',
 terms:[['Significant figures','Digits reflecting the precision supported by a measurement.'],['Standard deviation','A measure of the spread of observations around their mean.'],['Coefficient of variation','Standard deviation divided by mean, commonly expressed as a percentage.']],
 sections:[
 ['Units and reported precision','Carry extra digits during a calculation and round the final result according to the measurement and reporting requirements. For basic multiplication or division, the least precise measured input commonly limits significant figures; addition and subtraction commonly depend on decimal places. Exact counts and defined conversions are not uncertain measurements. Always write units and use dimensional analysis. A calculator’s many digits do not create extra instrument precision.'],
 ['Read pH as a logarithmic scale','At the introductory level, pH is approximately -log10 of hydrogen ion concentration in mol/L; strictly it is based on hydrogen ion activity. A decrease of one pH unit represents about ten times greater hydrogen ion concentration, not one additional unit of concentration. A solution at pH 3 has about 100 times the hydrogen ion concentration of one at pH 5. Buffer performance also depends on composition and capacity.'],
 ['Center and spread answer different questions','The mean averages values, the median is the middle ordered value, and the mode is the most frequent value. The sample standard deviation uses n-1 in its variance denominator. A small standard deviation indicates close agreement, not necessarily agreement with the true value. CV = SD/mean × 100% describes relative spread for appropriate ratio-scale measurements with a meaningful nonzero mean; it is not useful for every variable.'],
 ['Use statistics without hiding the data','Retain individual observations, sample size, units, and the method used. Averages can hide an instrument drift or one failed replicate. Compare measurements with predefined criteria and investigate unusual values. Do not remove an inconvenient point simply to lower SD. Technical replicate wells describe repeat measurement variation; they do not become independent biological specimens merely because there are several wells.']
 ],examples:[['Sample SD and CV','Measured values are 9, 10, and 11 mg/L.','Mean = 10 mg/L. Squared deviations sum to 2. Sample variance = 2/(3-1) = 1 (mg/L)²; sample SD = 1 mg/L. CV = 1/10 × 100 = 10%.'],['Logarithmic comparison','Compare pH 4 and pH 6 using the concentration approximation.','[H+] at pH 4 is 10^-4 mol/L and at pH 6 is 10^-6 mol/L. Their ratio is 100; pH 4 has about 100 times greater [H+].']],
 cases:[{prompt:'A pH change from 6 to 4 corresponds approximately to which hydrogen ion concentration change?',answer:'A 100-fold increase',wrong:['A twofold increase','A 100-fold decrease','No change'],why:'Two pH units correspond to 10² = 100 in the opposite direction for hydrogen ion concentration.'},{prompt:'For 9, 10, and 11 mg/L, what is the sample standard deviation?',answer:'1 mg/L',wrong:['0 mg/L','10 mg/L','2 mg/L'],why:'The squared deviations sum to 2; dividing by n-1 = 2 and taking the square root gives 1 mg/L.'}]
},
{
 id:'cell_physiology',domain:'d5',title:'Cell Physiology, Membranes & Model Organisms',
 intro:'Connect cellular structure and metabolism with culture behavior and selection of expression systems.',
 terms:[['Selective permeability','A membrane property that controls passage of substances.'],['Osmosis','Net water movement across a selectively permeable membrane driven by water chemical potential differences.'],['Expression host','An organism or cell system used to produce a gene product.']],
 sections:[
 ['Structure supports function','Prokaryotes lack a membrane-bound nucleus; eukaryotic cells contain a nucleus and other membrane-bound organelles. Both use membranes, genetic information, and ribosomes. Membranes regulate movement and support transport and signaling. A cell wall and a plasma membrane are different structures. Gram-stain behavior reflects envelope properties and the staining procedure; it does not alone identify a species or determine every safety requirement.'],
 ['Transport and the culture environment','Diffusion moves substances down a gradient, while active transport uses energy to move substances against a gradient. Osmotic conditions can change cell volume and compromise function. Nutrients, oxygen, temperature, pH, and waste accumulation affect growth. Changing several conditions simultaneously makes a cause difficult to isolate. An incubator setpoint does not prove the temperature, gas level, or humidity at every culture location meets requirements.'],
 ['Macromolecules work together','Proteins provide catalytic, structural, transport, and signaling functions. Lipids contribute to membranes and energy storage, carbohydrates support energy and structure, and nucleic acids store or transmit genetic information. Enzyme activity depends on structure and conditions. Protein quantity does not guarantee activity: misfolding, degradation, or unfavorable conditions can impair function even when an assay detects protein mass.'],
 ['Choose a host for the intended product','Bacteria, yeast, and mammalian cells differ in growth, costs, genetic tools, and protein processing. A host that grows quickly may not make the needed post-translational modifications. Promoters and vectors must function in the selected host. Transformation introduces genetic material into suitable cells; transfection commonly describes introduction into eukaryotic cells. Verify identity and expression instead of assuming antibiotic selection proves correct product production.']
 ],examples:[['Host selection','A target therapeutic protein requires processing that a bacterial system does not provide.','Evaluate an appropriate eukaryotic expression system rather than selecting only for fast bacterial growth. Confirm product attributes by suitable tests.'],['Culture comparison','A culture grows poorly after changes in both medium and temperature.','The comparison cannot isolate which change caused the effect. Use a planned experiment with defined variables and controls.']],
 cases:[{prompt:'An assay detects the expected protein amount but the activity test fails. Which statement is defensible?',answer:'Protein quantity does not by itself establish functional activity',wrong:['The activity test must be deleted','All detected proteins are correctly folded','The product is automatically acceptable'],why:'Identity, quantity, structure, and functional activity are distinct attributes.'},{prompt:'Which factor matters when choosing a host for a recombinant protein?',answer:'Whether the host can support the required product processing',wrong:['Only how quickly it grows','Only the color of the culture vessel','All hosts process proteins identically'],why:'Hosts differ in post-translational processing, expression machinery, and production requirements.'}]
},
{
 id:'modern_therapies',domain:'d5',title:'Monoclonal Antibodies, mRNA & Cell-Based Immunotherapy',
 intro:'Understand biotechnology product mechanisms and quality attributes without confusing different therapeutic platforms.',
 terms:[['Monoclonal antibody','An antibody product derived from a defined clone and directed at a particular target.'],['mRNA','A transcript that carries coding information used in translation.'],['CAR-T','T cells engineered to express a chimeric antigen receptor.']],
 sections:[
 ['Antibodies as biotechnology products','Antibodies bind particular molecular features called epitopes. Monoclonal antibody products can be manufactured using established cell production systems and purified for their intended use. Depending on design, binding may block signaling, mark a target for immune activity, or deliver a linked agent. Specific binding does not eliminate every off-target effect or manufacturing concern. Identity, purity, potency, and contamination controls remain important.'],
 ['mRNA supplies transient instructions','mRNA carries information that ribosomes translate into protein. A manufactured mRNA product must reach suitable cells and retain integrity long enough for its intended action. Delivery formulation and storage can affect performance. mRNA is different from DNA and is not the same thing as the encoded protein. The presence of RNA alone does not establish correct sequence, integrity, delivery, or biological activity.'],
 ['Cell-based immunotherapy changes the product','CAR-T involves engineering T cells to express a receptor that recognizes an intended target. The product contains living cells, so identity, viable cell number, functionality, and appropriate contamination controls are central. Autologous material originates from the same person receiving it; allogeneic material originates from another donor. Chain of identity and chain of custody are especially important when handling personalized cell materials.'],
 ['Compare mechanisms and evidence','An antibody product acts through its molecular binding properties, an mRNA product supplies instructions for protein production, and a cell therapy relies on living cell behavior. Manufacturing measurements must match those differences. A concentration assay cannot substitute for every potency assay. Students should explain mechanisms and quality needs; clinical suitability, dosing, and treatment decisions belong to authorized clinicians and product-specific evidence.']
 ],examples:[['Identity versus viability','A cell product has high viability but a mismatched recipient identifier.','Hold the product and follow the identity discrepancy procedure. High viability cannot compensate for uncertain chain of identity.'],['RNA integrity','RNA mass meets the target but integrity testing indicates degradation.','Investigate against the specified criteria. Sufficient mass does not establish intact coding material or expected activity.']],
 cases:[{prompt:'Which statement best describes an mRNA therapeutic platform?',answer:'It delivers coding instructions that cells can translate into protein',wrong:['It is always a living engineered cell','It is identical to the protein it encodes','It always permanently changes genomic DNA'],why:'mRNA serves as a translation template; it differs from DNA, protein, and cell products.'},{prompt:'Why is recipient identity especially important for an autologous cell product?',answer:'The cells originate from the same intended recipient',wrong:['Viability makes identity irrelevant','All cell products are interchangeable','A concentration result identifies the recipient'],why:'Autologous products require verified chain of identity; quality measurements cannot replace that connection.'}]
},
{
 id:'bioprocess_quality',domain:'d6',title:'Bioprocessing, Environmental Monitoring & CAPA',
 intro:'Follow a product from cell growth to purification and use deviations as evidence for controlled improvement.',
 terms:[['Upstream processing','Production steps that grow cells or generate the product before primary recovery.'],['Downstream processing','Recovery, purification, and related processing of the produced material.'],['CAPA','Corrective and preventive actions managed through a documented quality process.']],
 sections:[
 ['Follow the manufacturing process','Upstream processing can include inoculum development, media preparation, culture expansion, and controlled production in a bioreactor. Downstream processing can include harvest, clarification, concentration, purification, and formulation. The exact process depends on whether the product is a secreted protein, intracellular molecule, cell product, or other material. Maintain batch identity across transfers and record parameters; a downstream purification cannot automatically undo every upstream problem.'],
 ['Know the department responsibilities','Manufacturing executes approved production procedures; QC performs defined sampling and testing; QA oversees the quality system and authorized disposition processes; R&D develops and studies products and methods. Duties can overlap within an organization, but no individual should informally release a batch outside their authority. GLP and GMP have different scopes: nonclinical study controls and manufacturing quality requirements should not be treated as interchangeable labels.'],
 ['Environmental monitoring supplies evidence','Monitoring can assess viable or nonviable contamination in controlled spaces, using a planned approach to location, timing, sampling method, and interpretation. A clean-looking room is not proof of control. Review trends and excursions against defined limits. Sampling itself must be controlled, and an absence of growth does not prove every surface or product is sterile. Keep monitoring records linked to the relevant time, location, and process.'],
 ['Investigate and verify improvement','A correction addresses an immediate problem; corrective action addresses its cause to prevent recurrence. Document the deviation, assess affected material, investigate evidence, and implement authorized actions. Do not label every error as careless behavior without examining procedures, training, equipment, and workflow. Check effectiveness after implementation. Closing a CAPA form is not evidence that the action worked; meaningful follow-up measurements are needed.']
 ],examples:[['Correction versus corrective action','A mislabeled reagent is quarantined, and an investigation finds a confusing label template.','Quarantine addresses the immediate issue. An approved template change, training, and effectiveness check can address recurrence.'],['Monitoring excursion','A controlled-area result exceeds the site action limit during a batch.','Document, notify, and assess affected operations/material through the quality procedure. Do not release the batch solely because its final concentration test passed.']],
 cases:[{prompt:'Which action addresses recurrence rather than only the immediate labeling error?',answer:'Correct the verified label-template cause and check effectiveness',wrong:['Hide the incorrect label','Repeat the same process without review','Discard the investigation record'],why:'Corrective action targets the established cause and requires evidence that recurrence risk was reduced.'},{prompt:'Which activity is generally downstream processing?',answer:'Purification of product after harvest',wrong:['Expansion of the inoculum before production','Initial culture growth only','Recruiting laboratory staff'],why:'Downstream steps recover and purify material generated during upstream production.'}]
},
{
 id:'regulatory_privacy',domain:'d6',title:'Regulatory Evidence, Audits & Protection of Sensitive Data',
 intro:'Recognize regulated-product development and protect records through controlled access and accurate reporting.',
 terms:[['Audit trail','A retained record of relevant changes, identities, and times.'],['Access control','Limiting system actions and data access to authorized users.'],['Intellectual property','Protected creations or confidential knowledge with organizational value.']],
 sections:[
 ['Product type determines the pathway','Biotechnology products include drugs, biologics, devices, and other materials whose oversight differs. Development can involve research, nonclinical evaluation, clinical investigation where applicable, and regulatory review. Do not assume every product has the same pathway or that passing one laboratory test establishes approval. A technician supports evidence quality through documented methods, valid controls, and sample traceability, rather than making unsupported approval claims.'],
 ['Records must support reconstruction','Controlled SOPs, batch records, equipment logs, and deviation reports serve different purposes. Verify the approved version and complete required entries at the time of the work. Preserve original data and document justified corrections. An electronic audit trail supports accountability but does not excuse inaccurate input. Review must consider missing, altered, or selectively reported observations as well as the final summary.'],
 ['Apply appropriate confidentiality','Protect sample identifiers, personal information, proprietary methods, and unreleased results through authorized systems and access. HIPAA obligations depend on the covered entity or business associate context and the information involved; not every school laboratory record is automatically governed by HIPAA. Educational simulations should use synthetic patient data. Where applicable, follow privacy requirements and institutional policy, and disclose only through authorized channels.'],
 ['Prepare for an evidence-based audit','An audit examines compliance evidence and processes. Answer accurately within your knowledge, retrieve controlled records through the proper channel, and acknowledge uncertainty instead of inventing an answer. Report accidental disclosure or access promptly. Use individual accounts, protect credentials, and avoid moving restricted data to personal storage for convenience. Data security, record integrity, and scientific validity are related but distinct responsibilities.']
 ],examples:[['Audit response','An auditor asks for a missing equipment check record.','State what is known, retrieve available evidence, and notify the responsible person. Do not recreate a falsely contemporaneous check.'],['Simulation privacy','A classroom exercise needs a patient dataset.','Use synthetic records rather than real identifiable patient data copied from a clinical system.']],
 cases:[{prompt:'An equipment check was not documented. What is the defensible response?',answer:'Report the missing record and follow the deviation procedure',wrong:['Backdate a new record as if it were original','Invent a passing value','Delete the related batch records'],why:'A truthful investigation preserves integrity; fabricated contemporaneous evidence does not.'},{prompt:'Which dataset is appropriate for a classroom patient simulation?',answer:'Synthetic patient records',wrong:['Unapproved exports of real patient identifiers','A coworker’s medical record','Any clinical data if names are shortened'],why:'Synthetic data meets the educational need without unauthorized use of real patient information.'}]
},
{
 id:'equipment_selection',domain:'d7',title:'Glassware, Temperature Equipment & Measurement Fitness',
 intro:'Choose appropriate equipment and distinguish a displayed setpoint from verified conditions.',
 terms:[['To contain','A vessel calibration specifying the volume held under stated conditions.'],['To deliver','A calibration specifying the volume delivered using the specified technique.'],['Verification','A check that defined requirements are met.']],
 sections:[
 ['Choose glassware by the measurement','Beakers and flasks used for mixing often have approximate markings. A volumetric flask contains a specified final volume; calibrated pipets deliver a specified volume under defined conditions. Graduated cylinders suit intermediate precision needs. Read manufacturer markings and delivery instructions, including whether a final drop should be expelled. Applying a micropipette blowout habit to every glass pipet can create a volume error.'],
 ['Temperature equipment has different purposes','Water baths transfer heat through water, dry blocks through fitted solid wells, incubators maintain culture environments, and shakers or stirrers provide mixing. Compatibility, vessel placement, loading, and thermal equilibration matter. A display indicates a sensor or controller value, not proof every sample reached that temperature. Use required independent checks and allow the specified equilibration period.'],
 ['Calibration, verification, and maintenance differ','Calibration characterizes response against references; verification checks performance against a requirement; maintenance preserves function. An instrument can be calibrated yet fail a current check or be unsuitable for a particular range. Inspect status labels, overdue service, operating limits, and daily records. Remove or restrict equipment as required when performance is unacceptable. Never silently adjust a sample result to compensate for an uninvestigated instrument problem.'],
 ['Respond to drift or malfunction','Compare unexpected readings with controls and independent checks. Record the instrument, time, setpoint, actual observation, and potentially affected work. Notify the responsible person and use an approved alternative only when allowed. Restarting can clear a message without resolving its cause. Retain fault evidence and assess whether results obtained before discovery were affected. Equipment readiness includes documentation and safety, not merely power.']
 ],examples:[['Setpoint discrepancy','A bath displays 37.0°C; an approved independent check reads 34.5°C outside the allowed tolerance.','Stop using it for the affected task, report the failed check, and assess impacted work under the procedure. Do not treat the display as proof of correctness.'],['Glassware choice','Prepare a quantitative standard to exactly 100 mL.','Use appropriate volumetric glassware for final volume rather than approximate beaker graduations.']],
 cases:[{prompt:'Which vessel is most suitable for preparing a solution to a precise final volume?',answer:'An appropriate calibrated volumetric flask',wrong:['Any beaker with rough markings','A sample rack','An unmarked bottle judged by eye'],why:'The volumetric flask is calibrated to contain the specified volume under its stated conditions.'},{prompt:'An independent temperature check fails while the display is normal. What is appropriate?',answer:'Hold affected use and investigate according to the procedure',wrong:['Ignore the independent check','Change records to the displayed value','Release all prior work without assessment'],why:'The displayed setpoint does not establish verified sample conditions.'}]
},
{
 id:'containment_equipment',domain:'d7',title:'Biosafety Cabinets, Fume Hoods & Clean Airflow',
 intro:'Choose containment by hazard and understand why different airflow devices are not interchangeable.',
 terms:[['HEPA filtration','High-efficiency filtration that captures particles; it does not generally remove chemical vapors.'],['Containment','Controls that prevent hazardous material exposure or release.'],['Clean bench','An airflow device designed primarily to protect the work product.']],
 sections:[
 ['Select the right protection','A chemical fume hood captures hazardous vapors through its specified exhaust system. A biological safety cabinet provides biological containment according to its class and configuration. A clean bench primarily protects product and may direct air toward the operator, making it inappropriate for hazardous biological work. Do not choose equipment based only on a moving-air sensation. Determine personnel, product, and environmental protection needs through the risk assessment.'],
 ['Know the limits of a BSC','A properly operated Class II BSC uses inward airflow and filtered airflow to support personnel, product, and environmental protection, but chemical compatibility depends on its type, exhaust arrangement, and approved use. HEPA filters retain particles and do not generally capture volatile chemicals. A biological cabinet is not a universal substitute for a chemical fume hood. Obtain authorization for any chemical use and follow manufacturer and site requirements.'],
 ['Preserve airflow during work','Verify certification and operating status, use the prescribed sash position, and keep front and rear grilles clear. Arrange clean and used materials to reduce cross-contamination without overcrowding. Avoid rapid movements and unnecessary traffic that can disturb airflow. Follow the approved surface decontamination procedure and contact time. Open flames can disrupt airflow and create hazards; use only approved alternatives and procedures.'],
 ['Alarms and monitoring require action','An airflow alarm, obstructed grille, or overdue certification changes readiness. Stop or secure the task according to the local plan and notify the responsible person; do not silence the alarm and proceed. Cleanroom laminar or unidirectional airflow helps control particles but does not replace gowning, cleaning, environmental monitoring, or material controls. Flow patterns support contamination control only when the whole system is maintained.']
 ],examples:[['Volatile solvent','A procedure involves a hazardous volatile solvent and no biological material.','Use the containment specified by the chemical risk assessment, commonly a suitable fume hood. A recirculating HEPA BSC is not automatically adequate.'],['Blocked grille','A notebook covers a BSC front grille.','Remove the obstruction safely under the procedure and restore an arrangement that maintains airflow; assess any affected work.']],
 cases:[{prompt:'Why is a HEPA-filtered cabinet not automatically suitable for volatile chemical hazards?',answer:'HEPA filtration does not generally remove chemical vapors',wrong:['HEPA removes every gas','All cabinets have identical exhaust','Vapors behave exactly like large particles'],why:'Particle filtration and vapor containment are different functions; cabinet configuration and approved use matter.'},{prompt:'Which device primarily protects product and can direct air toward the operator?',answer:'A clean bench',wrong:['Every chemical fume hood','Every Class II BSC','A sealed autoclave chamber'],why:'A clean bench is not biological containment for hazardous material.'}]
},
{
 id:'study_design',domain:'d8',title:'Testable Questions, Replication & Scientific Communication',
 intro:'Turn a broad idea into a measurable comparison and distinguish evidence from unsupported conclusions.',
 terms:[['Experimental unit','The independently assigned entity to which a treatment is applied.'],['Biological replicate','An independent biological unit used to assess biological variation.'],['Confounding','Mixing of influences that prevents a clear interpretation of an effect.']],
 sections:[
 ['Write a question that can be tested','Specify the system, manipulated or compared factor, measurable outcome, and conditions. A hypothesis makes a prediction that evidence could contradict. Define the measurement, timing, and comparison before collecting data. A question such as whether a buffer pH changes enzyme activity becomes testable when the enzyme, pH levels, activity measurement, and controlled temperature are stated. Avoid changing the question after seeing the results without labeling it exploratory.'],
 ['Plan units, controls, and assignment','Identify the experimental unit and use appropriate controls. Random assignment can reduce systematic group differences, and blocking can account for known factors such as day or instrument. Blinding can reduce subjective measurement bias. Keep uncontrolled factors from tracking with treatment: if one group is measured on Monday and the other on Friday, day may be confounded with treatment. A control should answer a defined validity question.'],
 ['Replicates and sample size have different roles','Repeated wells from one culture provide technical replication; independent cultures provide biological replication. More wells do not turn one culture into many independent cultures. Sample size should reflect expected variability, the effect of interest, feasible resources, and the planned analysis. Small samples can leave large uncertainty; more samples do not repair systematic bias. Record failures and apply predefined exclusion rules transparently.'],
 ['Communicate what the evidence supports','Report methods, units, sample size, independent units, summary measures, and limitations. Graph labels and error-bar definitions must be explicit. Distinguish observed differences from causal conclusions and statistical evidence from practical importance. Follow responsible conduct of research: retain data, credit contributions, cite sources, and avoid fabrication, falsification, or plagiarism. An unexpected result is a reason to investigate, not to rewrite the data.']
 ],examples:[['Pseudoreplication','One culture is measured in six wells for treatment and one other culture in six wells for control.','There is one independent culture per condition, not six biological replicates per condition. Wells assess repeat measurement variation.'],['Testable question','An investigator asks, “Is this buffer better?”','Specify the enzyme, comparator buffer, measured reaction rate, pH, temperature, and time. The resulting question can be answered with defined observations.']],
 cases:[{prompt:'Six wells are measured from one culture. How many independent biological cultures does this provide?',answer:'One',wrong:['Six','Twelve','It depends only on the plate size'],why:'Technical repeat measurements do not create additional independent biological units.'},{prompt:'Treatment samples are all run Monday and controls all run Friday. What concern follows?',answer:'Day is confounded with treatment',wrong:['Randomization is proven','There can be no bias','The controls are automatically valid'],why:'A day-related change cannot be separated cleanly from the treatment difference.'}]
},
{
 id:'pca_data_review',domain:'d8',title:'PCA, Error Patterns & Multivariable Data Review',
 intro:'Read exploratory multivariable plots and investigate errors without overstating what a pattern proves.',
 terms:[['Principal component','A weighted combination of variables chosen to summarize variation.'],['Score','A sample coordinate on a principal component.'],['Loading','A variable contribution to a principal component.']],
 sections:[
 ['Why reduce dimensions','A dataset may contain many correlated measurements, such as signals at several wavelengths. PCA creates new orthogonal directions that summarize variation: the first component captures the greatest available variance, the next captures the greatest remaining variance subject to orthogonality. The components are combinations of measured variables, not new directly measured substances. Reducing dimensions can make patterns easier to see while leaving some variation outside the plotted components.'],
 ['Read scores and loadings together','A scores plot locates samples; nearby samples have similar projected measurements. Loadings help show which variables contribute to a component. Axis labels should include the explained variance where available. Samples separated on a plot differ along those projected combinations, but separation alone does not identify a mechanism or prove a treatment effect. Batch, instrument, handling, and data preparation can create apparent clusters.'],
 ['Preparation changes interpretation','Variables with large numeric scales can dominate an unscaled analysis. Centering and appropriate scaling depend on the data and question. Missing values, transformations, and exclusion decisions must be documented. Examine raw data and quality controls before interpreting a PCA pattern. A single unusual sample may indicate a real difference, labeling error, or instrument fault; the plot is a prompt for investigation, not permission to erase it.'],
 ['Connect error patterns to evidence','Random error increases scatter; systematic error can shift measurements consistently. Repeated checks can reveal drift, while reference materials can reveal bias. A precise instrument can be consistently wrong. Review standards, calibration, blanks, sample identity, and timing when a pattern appears. Report conclusions with uncertainty and limitations. PCA is exploratory and does not itself supply a causal claim, a p-value, or a validated pass/fail decision.']
 ],examples:[['Explained variance','PC1 explains 55% and PC2 explains 25% of variance.','The two-axis plot represents 80% of the variance, leaving 20% outside those axes. It does not show 80% accuracy or prove 80% of samples are correct.'],['Batch clusters','A PCA plot separates Monday samples from Friday samples, which were also different treatment groups.','Investigate batch/day effects and confounding. The plot cannot isolate treatment as the cause.']],
 cases:[{prompt:'PC1 explains 55% and PC2 25%. What does their plot summarize?',answer:'80% of the dataset variance',wrong:['80% classification accuracy','Every measured feature without loss','A p-value of 0.80'],why:'Explained variance adds across these orthogonal components; it is not classification accuracy or significance.'},{prompt:'PCA separates two sample groups. What is justified from the plot alone?',answer:'An exploratory difference needing contextual investigation',wrong:['A proven causal treatment effect','Permission to delete one cluster','A guaranteed diagnosis'],why:'PCA can expose structure from many sources, including batch effects; it does not establish causation.'}],
 sources:[{title:'NIST: Principal Components',url:'https://www.itl.nist.gov/div898/handbook/pmc/section5/pmc55.htm'}]
}
];

